//! Meter preset files against real artefacts (see `testdata/preset_files/README.md`): the 51 files on the owner's card are parsed
//! by Omega's reader, regenerated byte for byte by Omega's writer, and rebuilt from Tau Alpha's `presets.json` through the
//! factory import. Evidence label: host-tested against Tau Alpha's reference output; not run on a Pocket by Omega.

use std::{collections::BTreeMap, fs, path::PathBuf};
use tau_core::{
    meter_presets::MeterRegistry,
    preset_files::{self, PresetSet},
};

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/preset_files")
}

fn registry() -> MeterRegistry {
    MeterRegistry::from_json(&fs::read(root().join("meters_schema.json")).unwrap()).unwrap()
}

/// `<meter id>` -> file name -> bytes, for every meter folder on the card fixture.
fn card() -> BTreeMap<u16, BTreeMap<String, Vec<u8>>> {
    let mut out = BTreeMap::new();
    for dir in fs::read_dir(root().join("card/tau-presets"))
        .unwrap()
        .flatten()
    {
        let id: u16 = dir.file_name().to_string_lossy().parse().unwrap();
        let mut files = BTreeMap::new();
        for f in fs::read_dir(dir.path()).unwrap().flatten() {
            files.insert(
                f.file_name().to_string_lossy().into_owned(),
                fs::read(f.path()).unwrap(),
            );
        }
        out.insert(id, files);
    }
    out
}

#[test]
fn every_real_file_is_read_and_written_back_byte_for_byte() {
    let reg = registry();
    let card = card();
    assert_eq!(
        card.keys().copied().collect::<Vec<_>>(),
        [12, 13, 14, 15, 16, 17, 18]
    );
    let mut total = 0;
    for (id, files) in &card {
        let meter = reg.meters.iter().find(|m| u16::from(m.id) == *id).unwrap();
        let specs = preset_files::param_specs(meter).unwrap();
        let set = PresetSet::from_files(*id, files, &specs).unwrap();
        assert!(!set.presets.is_empty(), "{}", meter.key);
        let written = set.to_files(&specs).unwrap();
        assert_eq!(written.len(), files.len(), "{}: file count", meter.key);
        for (path, bytes) in &written {
            let name = path.rsplit('/').next().unwrap();
            assert_eq!(
                bytes, &files[name],
                "{}: {path} differs from the card's file",
                meter.key
            );
            total += 1;
        }
    }
    assert_eq!(total, 51);
}

#[test]
fn the_factory_import_rebuilds_the_cards_files_from_presets_json() {
    let reg = registry();
    let card = card();
    for (id, files) in &card {
        let meter = reg.meters.iter().find(|m| u16::from(m.id) == *id).unwrap();
        let specs = preset_files::param_specs(meter).unwrap();
        let json = fs::read(root().join("meters").join(&meter.key).join("presets.json")).unwrap();
        let set = preset_files::factory_set(meter, &json).unwrap();
        for (path, bytes) in set.to_files(&specs).unwrap() {
            let name = path.rsplit('/').next().unwrap();
            assert_eq!(bytes, files[name], "{} {path}", meter.key);
        }
    }
}

#[test]
fn a_real_preset_applies_to_the_values_in_its_source_json() {
    // Layered Wave's AURORA (id 0): the firmware's result (defaults, then the keys, clamped) is the preset's own values.
    let reg = registry();
    let lw = reg.find("layered_wave").unwrap();
    let specs = preset_files::param_specs(lw).unwrap();
    let file = &card()[&16]["p0.tpr"];
    let pre = preset_files::parse_preset(file).unwrap();
    assert_eq!(pre.name, "AURORA");
    let applied = preset_files::apply(&pre, &specs);
    let json: serde_json::Value =
        serde_json::from_slice(&fs::read(root().join("meters/layered_wave/presets.json")).unwrap())
            .unwrap();
    let want = &json["presets"][0]["values"];
    for (s, v) in specs.iter().zip(&applied) {
        if let Some(n) = want.get(&s.key).and_then(serde_json::Value::as_i64) {
            assert_eq!(*v, n, "{}", s.key);
        } else {
            assert_eq!(*v, s.default, "{} should be at its default", s.key);
        }
    }
}

#[test]
fn a_new_key_on_the_meter_leaves_old_presets_working() {
    // The reason for sparse, hash-keyed presets: add a parameter and every existing preset still reads, the new one at its default.
    let reg = registry();
    let mut lw = reg.find("layered_wave").unwrap().clone();
    let mut extra = lw.params[1].clone();
    extra.key = "brand_new_parameter".into();
    extra.default = extra.min;
    lw.params.push(extra);
    let specs = preset_files::param_specs(&lw).unwrap();
    let pre = preset_files::parse_preset(&card()[&16]["p3.tpr"]).unwrap();
    let applied = preset_files::apply(&pre, &specs);
    assert_eq!(*applied.last().unwrap(), specs.last().unwrap().default);
    assert_eq!(applied.len(), specs.len());
}

#[test]
fn the_real_capture_and_the_golden_layout_show_the_chosen_preset_by_name() {
    use tau_core::{diag::read_persisted_settings, persist_layout};
    let fixtures = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/persist_layout");
    // The DEV 213 capture has no preset file chosen (MPID words are 0): nothing is invented for it.
    let settings = read_persisted_settings(fixtures.join("dev213_interact_persist.json")).unwrap();
    let view = persist_layout::describe(&settings);
    assert_eq!(view.layout, persist_layout::Layout::New);
    assert!(
        !view
            .values
            .iter()
            .any(|v| v.label.starts_with("Meter slot") && v.label.ends_with(" preset")),
        "{:?}",
        view.values
    );
    // A word with preset id 4 chosen for slot 3 (word 15 bits 0..6 hold id + 1 = 5): shown by name when the resolver knows it.
    let mut w = persist_layout::words_from_settings(&settings);
    w[15] = persist_layout::NEW_MARK | 5;
    let mut s2 = settings.clone();
    for s in &mut s2 {
        if let Some(word) = persist_layout::word_of(s.id) {
            s.value = serde_json::json!(w[word]);
        }
    }
    let named = persist_layout::describe_with_names(&s2, &|slot, id| {
        (slot == 3 && id == 4).then(|| "AURORA".to_string())
    });
    let row = named
        .values
        .iter()
        .find(|v| v.label == "Meter slot 3 preset")
        .unwrap();
    assert_eq!(row.text, "AURORA (id 4)");
    let plain = persist_layout::describe(&s2);
    assert_eq!(
        plain
            .values
            .iter()
            .find(|v| v.label == "Meter slot 3 preset")
            .unwrap()
            .text,
        "preset id 4"
    );
}

fn scratch_card(tag: &str) -> PathBuf {
    use std::sync::atomic::{AtomicUsize, Ordering};
    static N: AtomicUsize = AtomicUsize::new(0);
    let dir = std::env::temp_dir().join(format!(
        "tau-presets-{tag}-{}-{}",
        std::process::id(),
        N.fetch_add(1, Ordering::SeqCst)
    ));
    let _ = fs::remove_dir_all(&dir);
    let common = dir.join("Assets/tau/common");
    fs::create_dir_all(dir.join("Cores")).unwrap();
    for (id, files) in card() {
        let d = common.join("tau-presets").join(id.to_string());
        fs::create_dir_all(&d).unwrap();
        for (name, bytes) in files {
            fs::write(d.join(&name), bytes).unwrap();
            // What the card really had: an AppleDouble stub beside every file.
            fs::write(d.join(format!("._{name}")), b"stub").unwrap();
        }
    }
    dir
}

#[test]
fn a_music_scan_and_the_problem_finder_leave_tau_presets_alone() {
    let dir = scratch_card("scan");
    let common = dir.join("Assets/tau/common");
    let scan = tau_core::scan_dir(&common, false).unwrap();
    assert!(scan.entries.is_empty(), "preset files are not tracks");
    assert!(
        scan.warnings
            .iter()
            .all(|w| !format!("{w:?}").contains("tau-presets")),
        "{:?}",
        scan.warnings
    );
    let problems = tau_core::problems::find_problems(&common, &scan.entries).unwrap();
    assert!(problems.is_empty(), "{problems:?}");
    assert_eq!(card_files(&common), 51 * 2, "nothing was removed or added");
    let _ = fs::remove_dir_all(&dir);
}

fn card_files(common: &std::path::Path) -> usize {
    walk(&common.join("tau-presets"))
}
fn walk(d: &std::path::Path) -> usize {
    fs::read_dir(d)
        .unwrap()
        .flatten()
        .map(|e| {
            if e.file_type().unwrap().is_dir() {
                walk(&e.path())
            } else {
                1
            }
        })
        .sum()
}

#[test]
fn the_eject_sweep_removes_the_stubs_beside_preset_files_and_keeps_every_preset_file() {
    let dir = scratch_card("tidy");
    let tidied = tau_core::card_tidy::tidy_card(&dir.join("Assets/tau/common"));
    assert_eq!(tidied.appledouble, 51);
    let common = dir.join("Assets/tau/common");
    assert_eq!(card_files(&common), 51);
    for (id, files) in card() {
        for (name, bytes) in files {
            assert_eq!(
                fs::read(common.join("tau-presets").join(id.to_string()).join(&name)).unwrap(),
                bytes
            );
        }
    }
    let _ = fs::remove_dir_all(&dir);
}

/// A package with a core file and the factory presets of two meters (16: three presets, 17: one), like the v0.7.0 release zip.
fn package_zip(tag: &str) -> PathBuf {
    use std::io::Write;
    let path =
        std::env::temp_dir().join(format!("tau-presets-pkg-{tag}-{}.zip", std::process::id()));
    let mut w = zip::ZipWriter::new(fs::File::create(&path).unwrap());
    let opts = zip::write::SimpleFileOptions::default();
    let mut put = |name: &str, bytes: &[u8]| {
        w.start_file(name, opts).unwrap();
        w.write_all(bytes).unwrap();
    };
    put("Cores/alfatreze.TAU/core.json", b"{}");
    for (id, files) in card().iter().filter(|(id, _)| matches!(**id, 16 | 17)) {
        for (name, bytes) in files {
            put(&format!("Assets/tau/common/tau-presets/{id}/{name}"), bytes);
        }
    }
    w.finish().unwrap();
    path
}

#[test]
fn an_update_never_overwrites_a_meter_folder_the_owner_already_has_but_seeds_a_new_one() {
    use tau_core::package;
    let dir = std::env::temp_dir().join(format!("tau-presets-install-{}", std::process::id()));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(dir.join("Cores")).unwrap();
    let zip = package_zip("seed");
    // The owner has edited meter 16 (an index with one preset and a changed p0); meter 17 is not on the card yet.
    let own = dir.join("Assets/tau/common/tau-presets/16");
    fs::create_dir_all(&own).unwrap();
    fs::write(own.join("index.tpi"), b"owner's index").unwrap();
    fs::write(own.join("p0.tpr"), b"owner's preset").unwrap();
    let plan = package::plan_install(&zip, &dir).unwrap();
    let c = card();
    assert_eq!(
        plan.kept_files,
        c[&16].len(),
        "every file of meter 16 is kept"
    );
    assert_eq!(plan.updated_files, 0);
    assert_eq!(
        plan.new_files,
        1 + c[&17].len(),
        "the core file and meter 17 are seeded"
    );
    package::execute_install(&zip, &dir, &plan, &plan.id).unwrap();
    assert_eq!(fs::read(own.join("index.tpi")).unwrap(), b"owner's index");
    assert_eq!(fs::read(own.join("p0.tpr")).unwrap(), b"owner's preset");
    assert!(
        !own.join("p1.tpr").exists(),
        "a preset the owner deleted does not come back"
    );
    for (name, bytes) in &c[&17] {
        assert_eq!(
            &fs::read(dir.join("Assets/tau/common/tau-presets/17").join(name)).unwrap(),
            bytes
        );
    }
    // Run it again: nothing left to do for the presets.
    let again = package::plan_install(&zip, &dir).unwrap();
    assert_eq!((again.new_files, again.updated_files), (0, 0));
    let _ = fs::remove_dir_all(&dir);
    let _ = fs::remove_file(zip);
}

#[test]
fn kept_for_user_only_matches_a_meter_folder_with_an_index() {
    use tau_core::package::kept_for_user;
    let dir = std::env::temp_dir().join(format!("tau-presets-kept-{}", std::process::id()));
    let _ = fs::remove_dir_all(&dir);
    let folder = dir.join("Assets/tau/common/tau-presets/16");
    fs::create_dir_all(&folder).unwrap();
    let p = "Assets/tau/common/tau-presets/16/p0.tpr";
    assert!(!kept_for_user(&dir, p), "no index yet: seed it");
    fs::write(folder.join("index.tpi"), b"x").unwrap();
    assert!(kept_for_user(&dir, p));
    assert!(kept_for_user(
        &dir,
        "Assets/tau/common/tau-presets/16/index.tpi"
    ));
    for other in [
        "Assets/tau/common/tau-presets/17/p0.tpr",
        "Assets/tau/common/tau-presets/16/sub/p0.tpr",
        "Assets/tau/common/other/16/p0.tpr",
        "Cores/alfatreze.TAU/core.json",
        "Assets/tau/common/tau-presets/abc/p0.tpr",
    ] {
        assert!(!kept_for_user(&dir, other), "{other}");
    }
    let _ = fs::remove_dir_all(&dir);
}
